-- Insere somente o novo modulo inativo e os 100 novos desafios inativos.
-- Seguro para producao: nao atualiza, nao apaga e nao altera desafios existentes.
-- Se algum ID ja existir, a linha correspondente sera ignorada por ON CONFLICT DO NOTHING.

begin;

insert into modules (id, track_id, title, description, slug, sort_order, unlock_rule, is_active)
values
  ('00000000-0000-0000-0000-000000000212', '00000000-0000-0000-0000-000000000101', 'Perguntas de negocio', 'Responda perguntas de negocio com consultas analiticas.', 'perguntas-de-negocio', 12, '{"type":"previous_module_completion","percentage":70}', false)
on conflict (id) do nothing;

insert into challenges (id, module_id, title, slug, type, difficulty, prompt, starter_sql, expected_sql, allowed_tables, setup_sql, validation_sql, base_points, explanation, tags, sort_order, is_active)
values
  ('00000000-0000-0000-0000-000000000411', '00000000-0000-0000-0000-000000000212', 'Receita total no mes', 'negocio-receita-total-mes', 'free_select', 'medium', 'Pergunta de negocio: qual foi a receita total da loja em fevereiro de 2026? Retorne `revenue_total` somando `amount` das transacoes `revenue` em `financial_transactions` no periodo de 2026-02-01 ate antes de 2026-03-01.', null, 'SELECT sum(ft.amount) AS revenue_total FROM challenge_data.financial_transactions ft WHERE ft.transaction_date >= DATE ''2026-02-01'' AND ft.transaction_date < DATE ''2026-03-01'' AND ft.type = ''revenue''', array['financial_transactions'], null, null, 20, 'Receita total usa apenas transacoes de receita dentro do periodo fechado.', array['select', 'draft'], 1, false),
  ('00000000-0000-0000-0000-000000000412', '00000000-0000-0000-0000-000000000212', 'Lucro liquido no mes', 'negocio-lucro-liquido-mes', 'free_select', 'medium', 'Pergunta de negocio: qual foi o lucro liquido da loja em fevereiro de 2026 considerando receitas positivas e `fee`, `shipping_cost` e `refund` como saidas? Retorne `net_profit`.', null, 'SELECT sum(CASE WHEN ft.type = ''revenue'' THEN ft.amount ELSE -ft.amount END) AS net_profit FROM challenge_data.financial_transactions ft WHERE ft.transaction_date >= DATE ''2026-02-01'' AND ft.transaction_date < DATE ''2026-03-01''', array['financial_transactions'], null, null, 20, 'O CASE transforma custos, taxas e estornos em valores negativos antes da soma.', array['select', 'draft'], 2, false),
  ('00000000-0000-0000-0000-000000000413', '00000000-0000-0000-0000-000000000212', 'Pedidos validos por status', 'negocio-pedidos-validos-por-status', 'free_select', 'medium', 'Pergunta de negocio: quantos pedidos validos houve por status em fevereiro de 2026? Considere status `paid`, `shipped` e `delivered`. Retorne `status` e `order_count`, ordenando por `order_count` decrescente e depois por `status` crescente.', null, 'SELECT o.status, count(*) AS order_count FROM challenge_data.orders o WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY o.status ORDER BY order_count DESC, o.status', array['orders'], null, null, 20, 'Agrupar por status mostra o volume operacional dos pedidos validos.', array['select', 'draft'], 3, false),
  ('00000000-0000-0000-0000-000000000414', '00000000-0000-0000-0000-000000000212', 'Ticket medio por status', 'negocio-ticket-medio-por-status', 'free_select', 'medium', 'Pergunta de negocio: qual foi o ticket medio dos pedidos por status em fevereiro de 2026? Retorne `status`, `order_count` e `average_order_value`, ordenando por `average_order_value` decrescente.', null, 'SELECT o.status, count(*) AS order_count, round(avg(o.total_amount), 2) AS average_order_value FROM challenge_data.orders o WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' GROUP BY o.status ORDER BY average_order_value DESC', array['orders'], null, null, 20, 'AVG resume o valor medio dos pedidos por grupo de status.', array['select', 'draft'], 4, false),
  ('00000000-0000-0000-0000-000000000415', '00000000-0000-0000-0000-000000000212', 'Categorias com maior receita', 'negocio-categorias-maior-receita', 'free_select', 'medium', 'Pergunta de negocio: quais categorias mais venderam em fevereiro de 2026? Retorne `category_name` e `sales_total`, somando `order_items.line_total` de pedidos `paid`, `shipped` ou `delivered`, ordenando por `sales_total` decrescente.', null, 'SELECT c.name AS category_name, sum(oi.line_total) AS sales_total FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id JOIN challenge_data.order_items oi ON oi.product_id = p.id JOIN challenge_data.orders o ON o.id = oi.order_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.name ORDER BY sales_total DESC', array['categories', 'products', 'order_items', 'orders'], null, null, 20, 'A receita por categoria vem dos itens vendidos conectados aos produtos e categorias.', array['select', 'draft'], 5, false),
  ('00000000-0000-0000-0000-000000000416', '00000000-0000-0000-0000-000000000212', 'Lucro bruto por categoria', 'negocio-lucro-bruto-por-categoria', 'free_select', 'medium', 'Pergunta de negocio: qual foi o lucro bruto estimado por categoria em fevereiro de 2026? Retorne `category_name` e `gross_profit`, usando `sum((price - cost) * quantity)` em pedidos validos, ordenando por `gross_profit` decrescente.', null, 'SELECT c.name AS category_name, sum((p.price - p.cost) * oi.quantity) AS gross_profit FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id JOIN challenge_data.order_items oi ON oi.product_id = p.id JOIN challenge_data.orders o ON o.id = oi.order_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.name ORDER BY gross_profit DESC', array['categories', 'products', 'order_items', 'orders'], null, null, 20, 'A margem bruta usa preco, custo e quantidade vendida por item.', array['select', 'draft'], 6, false),
  ('00000000-0000-0000-0000-000000000417', '00000000-0000-0000-0000-000000000212', 'Unidades vendidas por categoria', 'negocio-unidades-vendidas-categoria', 'free_select', 'medium', 'Pergunta de negocio: quais categorias venderam mais unidades em fevereiro de 2026? Retorne `category_name` e `units_sold`, somando `order_items.quantity` em pedidos validos, ordenando por `units_sold` decrescente e `category_name` crescente.', null, 'SELECT c.name AS category_name, sum(oi.quantity) AS units_sold FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id JOIN challenge_data.order_items oi ON oi.product_id = p.id JOIN challenge_data.orders o ON o.id = oi.order_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.name ORDER BY units_sold DESC, category_name', array['categories', 'products', 'order_items', 'orders'], null, null, 20, 'Quantidade vendida mede giro, diferente de faturamento.', array['select', 'draft'], 7, false),
  ('00000000-0000-0000-0000-000000000418', '00000000-0000-0000-0000-000000000212', 'Clientes que mais compraram', 'negocio-clientes-maior-gasto', 'free_select', 'medium', 'Pergunta de negocio: quais clientes mais compraram em fevereiro de 2026? Retorne `full_name` e `total_spent`, somando `orders.total_amount` de pedidos validos, ordenando por `total_spent` decrescente e limitando em 10.', null, 'SELECT c.full_name, sum(o.total_amount) AS total_spent FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.id, c.full_name ORDER BY total_spent DESC LIMIT 10', array['customers', 'orders'], null, null, 20, 'O ranking de clientes soma pedidos validos por cliente.', array['select', 'draft'], 8, false),
  ('00000000-0000-0000-0000-000000000419', '00000000-0000-0000-0000-000000000212', 'Receita por estado', 'negocio-receita-por-estado', 'free_select', 'medium', 'Pergunta de negocio: quais estados geraram mais receita em pedidos validos em fevereiro de 2026? Retorne `state` e `sales_total`, ordenando por `sales_total` decrescente.', null, 'SELECT c.state, sum(o.total_amount) AS sales_total FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.state ORDER BY sales_total DESC', array['customers', 'orders'], null, null, 20, 'Cruzar clientes e pedidos permite analisar receita por estado.', array['select', 'draft'], 9, false),
  ('00000000-0000-0000-0000-000000000420', '00000000-0000-0000-0000-000000000212', 'Receita por metodo de pagamento', 'negocio-receita-por-metodo-pagamento', 'free_select', 'medium', 'Pergunta de negocio: quais metodos de pagamento concentraram mais valor pago em fevereiro de 2026? Retorne `payment_method`, `payment_count` e `paid_total`, considerando apenas pagamentos `paid`, ordenando por `paid_total` decrescente.', null, 'SELECT p.payment_method, count(*) AS payment_count, sum(p.amount) AS paid_total FROM challenge_data.payments p WHERE p.paid_at >= TIMESTAMP ''2026-02-01'' AND p.paid_at < TIMESTAMP ''2026-03-01'' AND p.status = ''paid'' GROUP BY p.payment_method ORDER BY paid_total DESC', array['payments'], null, null, 20, 'Pagamentos pagos por metodo mostram como a receita foi liquidada.', array['select', 'draft'], 10, false),
  ('00000000-0000-0000-0000-000000000421', '00000000-0000-0000-0000-000000000212', 'Pedidos com frete gratis', 'negocio-pedidos-com-frete-gratis', 'free_select', 'medium', 'Pergunta de negocio: quantos pedidos tiveram frete gratis em fevereiro de 2026? Retorne `free_shipping_orders` contando pedidos com `shipping_amount = 0`.', null, 'SELECT count(*) AS free_shipping_orders FROM challenge_data.orders o WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.shipping_amount = 0', array['orders'], null, null, 20, 'Pedidos com frete zero indicam uso de promocao ou condicao comercial.', array['select', 'draft'], 11, false),
  ('00000000-0000-0000-0000-000000000422', '00000000-0000-0000-0000-000000000212', 'Descontos por dia', 'negocio-descontos-por-dia', 'free_select', 'medium', 'Pergunta de negocio: quanto desconto foi concedido por dia em fevereiro de 2026? Retorne `order_day` e `discount_total`, considerando apenas pedidos com desconto maior que zero, ordenando por `order_day` crescente.', null, 'SELECT o.order_date::date AS order_day, sum(o.discount_amount) AS discount_total FROM challenge_data.orders o WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.discount_amount > 0 GROUP BY order_day ORDER BY order_day', array['orders'], null, null, 20, 'Agrupar por dia mostra quando os descontos foram usados.', array['select', 'draft'], 12, false),
  ('00000000-0000-0000-0000-000000000423', '00000000-0000-0000-0000-000000000212', 'Produtos com maior receita', 'negocio-produtos-maior-receita', 'free_select', 'medium', 'Pergunta de negocio: quais produtos geraram mais receita em pedidos validos de fevereiro de 2026? Retorne `product_name` e `sales_total`, ordenando por `sales_total` decrescente e limitando em 10.', null, 'SELECT p.name AS product_name, sum(oi.line_total) AS sales_total FROM challenge_data.products p JOIN challenge_data.order_items oi ON oi.product_id = p.id JOIN challenge_data.orders o ON o.id = oi.order_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY p.id, p.name ORDER BY sales_total DESC LIMIT 10', array['products', 'order_items', 'orders'], null, null, 20, 'Produto com maior receita usa soma de line_total em pedidos validos.', array['select', 'draft'], 13, false),
  ('00000000-0000-0000-0000-000000000424', '00000000-0000-0000-0000-000000000212', 'Produtos com maior lucro bruto', 'negocio-produtos-maior-lucro-bruto', 'free_select', 'medium', 'Pergunta de negocio: quais produtos tiveram maior lucro bruto estimado em fevereiro de 2026? Retorne `product_name` e `gross_profit`, usando `(price - cost) * quantity` em pedidos validos, ordenando por `gross_profit` decrescente.', null, 'SELECT p.name AS product_name, sum((p.price - p.cost) * oi.quantity) AS gross_profit FROM challenge_data.products p JOIN challenge_data.order_items oi ON oi.product_id = p.id JOIN challenge_data.orders o ON o.id = oi.order_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY p.id, p.name ORDER BY gross_profit DESC', array['products', 'order_items', 'orders'], null, null, 20, 'Lucro bruto por produto combina margem unitaria e quantidade vendida.', array['select', 'draft'], 14, false),
  ('00000000-0000-0000-0000-000000000425', '00000000-0000-0000-0000-000000000212', 'Receita diaria', 'negocio-receita-diaria', 'free_select', 'medium', 'Pergunta de negocio: qual foi a receita diaria de pedidos validos em fevereiro de 2026? Retorne `order_day` e `sales_total`, ordenando por `order_day` crescente.', null, 'SELECT o.order_date::date AS order_day, sum(o.total_amount) AS sales_total FROM challenge_data.orders o WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY order_day ORDER BY order_day', array['orders'], null, null, 20, 'Receita diaria ajuda a acompanhar tendencia no periodo.', array['select', 'draft'], 15, false),
  ('00000000-0000-0000-0000-000000000426', '00000000-0000-0000-0000-000000000212', 'Transacoes por tipo', 'negocio-transacoes-por-tipo', 'free_select', 'medium', 'Pergunta de negocio: qual foi o total financeiro por tipo de transacao em fevereiro de 2026? Retorne `type`, `transaction_count` e `total_amount`, ordenando por `total_amount` decrescente.', null, 'SELECT ft.type, count(*) AS transaction_count, sum(ft.amount) AS total_amount FROM challenge_data.financial_transactions ft WHERE ft.transaction_date >= DATE ''2026-02-01'' AND ft.transaction_date < DATE ''2026-03-01'' GROUP BY ft.type ORDER BY total_amount DESC', array['financial_transactions'], null, null, 20, 'O agrupamento por tipo separa receitas, taxas, fretes e estornos.', array['select', 'draft'], 16, false),
  ('00000000-0000-0000-0000-000000000427', '00000000-0000-0000-0000-000000000212', 'Entregas por transportadora', 'negocio-entregas-por-transportadora', 'free_select', 'medium', 'Pergunta de negocio: quantos pedidos entregues cada transportadora concluiu em fevereiro de 2026? Retorne `carrier` e `delivered_count`, considerando `shipments.status = ''delivered''`, ordenando por `delivered_count` decrescente.', null, 'SELECT s.carrier, count(*) AS delivered_count FROM challenge_data.shipments s WHERE s.delivered_at >= TIMESTAMP ''2026-02-01'' AND s.delivered_at < TIMESTAMP ''2026-03-01'' AND s.status = ''delivered'' GROUP BY s.carrier ORDER BY delivered_count DESC', array['shipments'], null, null, 20, 'Contar entregas concluidas por transportadora mede desempenho logistico basico.', array['select', 'draft'], 17, false),
  ('00000000-0000-0000-0000-000000000428', '00000000-0000-0000-0000-000000000212', 'Pedidos sem pagamento aprovado', 'negocio-pedidos-sem-pagamento-aprovado', 'free_select', 'medium', 'Pergunta de negocio: quais pedidos de fevereiro de 2026 nao possuem pagamento `paid`? Retorne `order_number` e `status`, usando `LEFT JOIN` com pagamentos pagos, ordenando por `order_number` crescente.', null, 'SELECT o.order_number, o.status FROM challenge_data.orders o LEFT JOIN challenge_data.payments p ON p.order_id = o.id AND p.status = ''paid'' WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND p.id IS NULL ORDER BY o.order_number', array['orders', 'payments'], null, null, 20, 'LEFT JOIN com IS NULL encontra pedidos sem pagamento aprovado.', array['select', 'draft'], 18, false),
  ('00000000-0000-0000-0000-000000000429', '00000000-0000-0000-0000-000000000212', 'Estoque por categoria', 'negocio-estoque-por-categoria', 'free_select', 'medium', 'Pergunta de negocio: qual e o estoque atual por categoria? Retorne `category_name`, `product_count` e `total_stock`, ordenando por `total_stock` decrescente.', null, 'SELECT c.name AS category_name, count(p.id) AS product_count, sum(p.stock_quantity) AS total_stock FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id GROUP BY c.name ORDER BY total_stock DESC', array['categories', 'products'], null, null, 20, 'Estoque por categoria cruza a dimensao categoria com produtos cadastrados.', array['select', 'draft'], 19, false),
  ('00000000-0000-0000-0000-000000000430', '00000000-0000-0000-0000-000000000212', 'Produtos ativos sem estoque', 'negocio-produtos-ativos-sem-estoque', 'free_select', 'medium', 'Pergunta de negocio: quais produtos ativos estao sem estoque? Retorne `category_name`, `product_name` e `stock_quantity`, filtrando `active = true` e `stock_quantity = 0`, ordenando por `category_name` e `product_name`.', null, 'SELECT c.name AS category_name, p.name AS product_name, p.stock_quantity FROM challenge_data.products p JOIN challenge_data.categories c ON c.id = p.category_id WHERE p.active = true AND p.stock_quantity = 0 ORDER BY category_name, product_name', array['products', 'categories'], null, null, 20, 'Produtos ativos sem estoque indicam ruptura operacional.', array['select', 'draft'], 20, false),
  ('00000000-0000-0000-0000-000000000431', '00000000-0000-0000-0000-000000000212', 'Participacao da receita por categoria', 'negocio-participacao-receita-categoria', 'free_select', 'hard', 'Pergunta de negocio: qual a participacao percentual de cada categoria na receita valida de fevereiro de 2026? Retorne `category_name`, `sales_total` e `sales_share_pct`, ordenando por `sales_total` decrescente.', null, 'SELECT c.name AS category_name, sum(oi.line_total) AS sales_total, round(100 * sum(oi.line_total) / sum(sum(oi.line_total)) OVER (), 2) AS sales_share_pct FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id JOIN challenge_data.order_items oi ON oi.product_id = p.id JOIN challenge_data.orders o ON o.id = oi.order_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.name ORDER BY sales_total DESC', array['categories', 'products', 'order_items', 'orders'], null, null, 35, 'A janela sobre a soma agregada calcula participacao no total geral.', array['select', 'draft'], 21, false),
  ('00000000-0000-0000-0000-000000000432', '00000000-0000-0000-0000-000000000212', 'Lucro liquido por pedido', 'negocio-lucro-liquido-por-pedido', 'free_select', 'hard', 'Pergunta de negocio: qual foi o lucro liquido financeiro por pedido em fevereiro de 2026? Retorne `order_number`, `full_name` e `net_amount`, somando receitas positivas e demais tipos negativos, ordenando por `net_amount` decrescente.', null, 'SELECT o.order_number, c.full_name, sum(CASE WHEN ft.type = ''revenue'' THEN ft.amount ELSE -ft.amount END) AS net_amount FROM challenge_data.orders o JOIN challenge_data.customers c ON c.id = o.customer_id JOIN challenge_data.financial_transactions ft ON ft.order_id = o.id WHERE ft.transaction_date >= DATE ''2026-02-01'' AND ft.transaction_date < DATE ''2026-03-01'' GROUP BY o.order_number, c.full_name ORDER BY net_amount DESC', array['orders', 'customers', 'financial_transactions'], null, null, 35, 'O lucro liquido por pedido vem das transacoes financeiras ligadas ao pedido.', array['select', 'draft'], 22, false),
  ('00000000-0000-0000-0000-000000000433', '00000000-0000-0000-0000-000000000212', 'Lucro bruto por cliente', 'negocio-lucro-bruto-por-cliente', 'free_select', 'hard', 'Pergunta de negocio: quais clientes geraram maior lucro bruto em pedidos validos de fevereiro de 2026? Retorne `full_name`, `order_count` e `gross_profit`, ordenando por `gross_profit` decrescente e limitando em 10.', null, 'SELECT c.full_name, count(DISTINCT o.id) AS order_count, sum((p.price - p.cost) * oi.quantity) AS gross_profit FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id JOIN challenge_data.order_items oi ON oi.order_id = o.id JOIN challenge_data.products p ON p.id = oi.product_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.id, c.full_name ORDER BY gross_profit DESC LIMIT 10', array['customers', 'orders', 'order_items', 'products'], null, null, 35, 'A margem bruta por cliente considera os itens comprados em pedidos validos.', array['select', 'draft'], 23, false),
  ('00000000-0000-0000-0000-000000000434', '00000000-0000-0000-0000-000000000212', 'Giro e margem por produto', 'negocio-giro-margem-produto', 'free_select', 'hard', 'Pergunta de negocio: quais produtos combinam maior giro e margem em fevereiro de 2026? Retorne `product_name`, `units_sold` e `gross_profit`, considerando pedidos validos, ordenando por `units_sold` decrescente e `gross_profit` decrescente.', null, 'SELECT p.name AS product_name, sum(oi.quantity) AS units_sold, sum((p.price - p.cost) * oi.quantity) AS gross_profit FROM challenge_data.products p JOIN challenge_data.order_items oi ON oi.product_id = p.id JOIN challenge_data.orders o ON o.id = oi.order_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY p.id, p.name ORDER BY units_sold DESC, gross_profit DESC', array['products', 'order_items', 'orders'], null, null, 35, 'Giro e margem juntos ajudam a priorizar produtos importantes.', array['select', 'draft'], 24, false),
  ('00000000-0000-0000-0000-000000000435', '00000000-0000-0000-0000-000000000212', 'Estoque e vendas por categoria', 'negocio-estoque-vendas-categoria', 'free_select', 'hard', 'Pergunta de negocio: compare estoque atual e vendas por categoria em fevereiro de 2026. Retorne `category_name`, `total_stock` e `sales_total`, usando CTEs `category_stock` e `category_sales`, ordenando por `sales_total` decrescente.', null, 'WITH category_stock AS (SELECT c.id, c.name AS category_name, sum(p.stock_quantity) AS total_stock FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id GROUP BY c.id, c.name), category_sales AS (SELECT c.id, sum(oi.line_total) AS sales_total FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id JOIN challenge_data.order_items oi ON oi.product_id = p.id JOIN challenge_data.orders o ON o.id = oi.order_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.id) SELECT cs.category_name, cs.total_stock, coalesce(s.sales_total, 0) AS sales_total FROM category_stock cs LEFT JOIN category_sales s ON s.id = cs.id ORDER BY sales_total DESC', array['categories', 'products', 'order_items', 'orders'], null, null, 35, 'Separar estoque e vendas em CTEs evita multiplicar estoque por item vendido.', array['select', 'draft'], 25, false),
  ('00000000-0000-0000-0000-000000000436', '00000000-0000-0000-0000-000000000212', 'Funil pagamento entrega', 'negocio-funil-pagamento-entrega', 'free_select', 'hard', 'Pergunta de negocio: como os pedidos de fevereiro de 2026 se distribuem entre status do pedido, pagamento e entrega? Retorne `order_status`, `payment_status`, `shipment_status` e `order_count`, ordenando por `order_count` decrescente.', null, 'SELECT o.status AS order_status, p.status AS payment_status, coalesce(s.status, ''sem_entrega'') AS shipment_status, count(*) AS order_count FROM challenge_data.orders o LEFT JOIN challenge_data.payments p ON p.order_id = o.id LEFT JOIN challenge_data.shipments s ON s.order_id = o.id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' GROUP BY o.status, p.status, coalesce(s.status, ''sem_entrega'') ORDER BY order_count DESC', array['orders', 'payments', 'shipments'], null, null, 35, 'O funil combina tres estados operacionais do pedido.', array['select', 'draft'], 26, false),
  ('00000000-0000-0000-0000-000000000437', '00000000-0000-0000-0000-000000000212', 'Pedidos validos sem entrega', 'negocio-pedidos-validos-sem-entrega', 'free_select', 'hard', 'Pergunta de negocio: quais pedidos validos de fevereiro de 2026 ainda nao possuem entrega registrada? Retorne `order_number`, `status` e `total_amount`, usando LEFT JOIN com `shipments`, ordenando por `total_amount` decrescente.', null, 'SELECT o.order_number, o.status, o.total_amount FROM challenge_data.orders o LEFT JOIN challenge_data.shipments s ON s.order_id = o.id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') AND s.id IS NULL ORDER BY o.total_amount DESC', array['orders', 'shipments'], null, null, 35, 'LEFT JOIN revela pedidos validos que ainda nao entraram no fluxo logistico.', array['select', 'draft'], 27, false),
  ('00000000-0000-0000-0000-000000000438', '00000000-0000-0000-0000-000000000212', 'Pagamentos pagos por dia e metodo', 'negocio-pagamentos-dia-metodo', 'free_select', 'hard', 'Pergunta de negocio: qual valor pago por dia e metodo em fevereiro de 2026? Retorne `payment_day`, `payment_method`, `payment_count` e `paid_total`, considerando `payments.status = ''paid''`, ordenando por `payment_day` e `paid_total` decrescente.', null, 'SELECT p.paid_at::date AS payment_day, p.payment_method, count(*) AS payment_count, sum(p.amount) AS paid_total FROM challenge_data.payments p WHERE p.paid_at >= TIMESTAMP ''2026-02-01'' AND p.paid_at < TIMESTAMP ''2026-03-01'' AND p.status = ''paid'' GROUP BY payment_day, p.payment_method ORDER BY payment_day, paid_total DESC', array['payments'], null, null, 35, 'A visao por dia e metodo ajuda a conciliar recebimentos.', array['select', 'draft'], 28, false),
  ('00000000-0000-0000-0000-000000000439', '00000000-0000-0000-0000-000000000212', 'Estornos por cliente', 'negocio-estornos-por-cliente', 'free_select', 'hard', 'Pergunta de negocio: quais clientes tiveram maior valor estornado em fevereiro de 2026? Retorne `full_name`, `refund_count` e `refund_total`, considerando transacoes `refund`, ordenando por `refund_total` decrescente.', null, 'SELECT c.full_name, count(*) AS refund_count, sum(ft.amount) AS refund_total FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id JOIN challenge_data.financial_transactions ft ON ft.order_id = o.id WHERE ft.transaction_date >= DATE ''2026-02-01'' AND ft.transaction_date < DATE ''2026-03-01'' AND ft.type = ''refund'' GROUP BY c.id, c.full_name ORDER BY refund_total DESC', array['customers', 'orders', 'financial_transactions'], null, null, 35, 'Estornos por cliente cruzam transacoes financeiras com pedidos e clientes.', array['select', 'draft'], 29, false),
  ('00000000-0000-0000-0000-000000000440', '00000000-0000-0000-0000-000000000212', 'Ranking de estados por receita', 'negocio-ranking-estados-receita', 'free_select', 'hard', 'Pergunta de negocio: gere o ranking dos estados por receita valida em fevereiro de 2026. Retorne `state_rank`, `state` e `sales_total`, usando `rank()` por `sales_total` decrescente.', null, 'SELECT rank() OVER (ORDER BY sum(o.total_amount) DESC) AS state_rank, c.state, sum(o.total_amount) AS sales_total FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.state ORDER BY state_rank, c.state', array['customers', 'orders'], null, null, 35, 'A funcao de janela ranqueia os estados apos a agregacao.', array['select', 'draft'], 30, false),
  ('00000000-0000-0000-0000-000000000441', '00000000-0000-0000-0000-000000000212', 'Compra media por cliente ativo', 'negocio-compra-media-cliente-ativo', 'free_select', 'hard', 'Pergunta de negocio: qual o gasto medio por pedido dos clientes com pedidos validos em fevereiro de 2026? Retorne `full_name`, `order_count`, `total_spent` e `average_order_value`, ordenando por `average_order_value` decrescente.', null, 'SELECT c.full_name, count(o.id) AS order_count, sum(o.total_amount) AS total_spent, round(avg(o.total_amount), 2) AS average_order_value FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.id, c.full_name ORDER BY average_order_value DESC', array['customers', 'orders'], null, null, 35, 'A media por pedido identifica clientes de ticket mais alto.', array['select', 'draft'], 31, false),
  ('00000000-0000-0000-0000-000000000442', '00000000-0000-0000-0000-000000000212', 'Produtos acima da media da categoria', 'negocio-produtos-acima-media-categoria', 'free_select', 'hard', 'Pergunta de negocio: quais produtos ativos tem preco acima da media da propria categoria? Use uma CTE `category_average`. Retorne `category_name`, `product_name`, `price` e `average_price`, ordenando por `category_name` e `price` decrescente.', null, 'WITH category_average AS (SELECT category_id, round(avg(price), 2) AS average_price FROM challenge_data.products WHERE active = true GROUP BY category_id) SELECT c.name AS category_name, p.name AS product_name, p.price, ca.average_price FROM challenge_data.products p JOIN challenge_data.categories c ON c.id = p.category_id JOIN category_average ca ON ca.category_id = p.category_id WHERE p.active = true AND p.price > ca.average_price ORDER BY category_name, p.price DESC', array['products', 'categories'], null, null, 35, 'Comparar produto com media da categoria exige uma etapa agregada antes do filtro.', array['select', 'draft'], 32, false),
  ('00000000-0000-0000-0000-000000000443', '00000000-0000-0000-0000-000000000212', 'Preco medio e margem media por categoria', 'negocio-preco-margem-media-categoria', 'free_select', 'hard', 'Pergunta de negocio: qual o preco medio e a margem media dos produtos ativos por categoria? Retorne `category_name`, `active_products`, `average_price` e `average_margin`, ordenando por `average_margin` decrescente.', null, 'SELECT c.name AS category_name, count(p.id) AS active_products, round(avg(p.price), 2) AS average_price, round(avg(p.price - p.cost), 2) AS average_margin FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id WHERE p.active = true GROUP BY c.name ORDER BY average_margin DESC', array['categories', 'products'], null, null, 35, 'A margem media de cadastro usa preco menos custo em produtos ativos.', array['select', 'draft'], 33, false),
  ('00000000-0000-0000-0000-000000000444', '00000000-0000-0000-0000-000000000212', 'Margem bruta por dia', 'negocio-margem-bruta-por-dia', 'free_select', 'hard', 'Pergunta de negocio: qual foi a margem bruta estimada por dia em pedidos validos de fevereiro de 2026? Retorne `order_day`, `sales_total` e `gross_profit`, ordenando por `order_day` crescente.', null, 'SELECT o.order_date::date AS order_day, sum(oi.line_total) AS sales_total, sum((p.price - p.cost) * oi.quantity) AS gross_profit FROM challenge_data.orders o JOIN challenge_data.order_items oi ON oi.order_id = o.id JOIN challenge_data.products p ON p.id = oi.product_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY order_day ORDER BY order_day', array['orders', 'order_items', 'products'], null, null, 35, 'Margem diaria combina dados de pedido com os itens vendidos.', array['select', 'draft'], 34, false),
  ('00000000-0000-0000-0000-000000000445', '00000000-0000-0000-0000-000000000212', 'Clientes novos com pedido', 'negocio-clientes-novos-com-pedido', 'free_select', 'hard', 'Pergunta de negocio: quais clientes cadastrados em janeiro de 2026 fizeram pedidos validos em fevereiro de 2026? Retorne `full_name`, `created_at`, `order_count` e `total_spent`, ordenando por `total_spent` decrescente.', null, 'SELECT c.full_name, c.created_at, count(o.id) AS order_count, sum(o.total_amount) AS total_spent FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id WHERE c.created_at >= TIMESTAMP ''2026-01-01'' AND c.created_at < TIMESTAMP ''2026-02-01'' AND o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.id, c.full_name, c.created_at ORDER BY total_spent DESC', array['customers', 'orders'], null, null, 35, 'Cruzar data de cadastro com pedidos mede ativacao de clientes novos.', array['select', 'draft'], 35, false),
  ('00000000-0000-0000-0000-000000000446', '00000000-0000-0000-0000-000000000212', 'Tempo medio de entrega por transportadora', 'negocio-tempo-medio-entrega-transportadora', 'free_select', 'hard', 'Pergunta de negocio: qual o tempo medio de entrega em dias por transportadora para entregas concluidas em fevereiro de 2026? Retorne `carrier`, `delivered_count` e `average_delivery_days`, ordenando por `average_delivery_days` crescente.', null, 'SELECT s.carrier, count(*) AS delivered_count, round(avg(extract(epoch FROM (s.delivered_at - s.shipped_at)) / 86400), 2) AS average_delivery_days FROM challenge_data.shipments s WHERE s.delivered_at >= TIMESTAMP ''2026-02-01'' AND s.delivered_at < TIMESTAMP ''2026-03-01'' AND s.shipped_at IS NOT NULL AND s.delivered_at IS NOT NULL GROUP BY s.carrier ORDER BY average_delivery_days', array['shipments'], null, null, 35, 'A diferenca entre entrega e envio convertida em dias mede prazo medio.', array['select', 'draft'], 36, false),
  ('00000000-0000-0000-0000-000000000447', '00000000-0000-0000-0000-000000000212', 'Falhas de pagamento por status do pedido', 'negocio-falhas-pagamento-status-pedido', 'free_select', 'hard', 'Pergunta de negocio: quais status de pedido concentram pagamentos falhos em fevereiro de 2026? Retorne `order_status`, `failed_payments` e `failed_amount`, considerando `payments.status = ''failed''`, ordenando por `failed_amount` decrescente.', null, 'SELECT o.status AS order_status, count(p.id) AS failed_payments, sum(p.amount) AS failed_amount FROM challenge_data.orders o JOIN challenge_data.payments p ON p.order_id = o.id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND p.status = ''failed'' GROUP BY o.status ORDER BY failed_amount DESC', array['orders', 'payments'], null, null, 35, 'Pagamentos falhos ligados ao status do pedido ajudam a identificar perdas.', array['select', 'draft'], 37, false),
  ('00000000-0000-0000-0000-000000000448', '00000000-0000-0000-0000-000000000212', 'Clientes com pedidos pagos e cancelados', 'negocio-clientes-pagos-cancelados', 'free_select', 'hard', 'Pergunta de negocio: quais clientes tiveram pedidos pagos ou entregues e tambem pedidos cancelados ou estornados em fevereiro de 2026? Retorne `full_name`, `valid_orders` e `problem_orders`, ordenando por `problem_orders` decrescente.', null, 'SELECT c.full_name, count(*) FILTER (WHERE o.status IN (''paid'', ''shipped'', ''delivered'')) AS valid_orders, count(*) FILTER (WHERE o.status IN (''cancelled'', ''refunded'')) AS problem_orders FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' GROUP BY c.id, c.full_name HAVING count(*) FILTER (WHERE o.status IN (''paid'', ''shipped'', ''delivered'')) > 0 AND count(*) FILTER (WHERE o.status IN (''cancelled'', ''refunded'')) > 0 ORDER BY problem_orders DESC, c.full_name', array['customers', 'orders'], null, null, 35, 'FILTER permite contar subconjuntos de status dentro do mesmo agrupamento.', array['select', 'draft'], 38, false),
  ('00000000-0000-0000-0000-000000000449', '00000000-0000-0000-0000-000000000212', 'Categorias sem venda valida', 'negocio-categorias-sem-venda-valida', 'free_select', 'hard', 'Pergunta de negocio: quais categorias nao tiveram venda em pedidos validos de fevereiro de 2026? Retorne `category_name` e `valid_sales_total`, usando LEFT JOIN, ordenando por `category_name`.', null, 'SELECT c.name AS category_name, coalesce(sum(CASE WHEN o.id IS NOT NULL THEN oi.line_total ELSE 0 END), 0) AS valid_sales_total FROM challenge_data.categories c LEFT JOIN challenge_data.products p ON p.category_id = c.id LEFT JOIN challenge_data.order_items oi ON oi.product_id = p.id LEFT JOIN challenge_data.orders o ON o.id = oi.order_id AND o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.name HAVING coalesce(sum(CASE WHEN o.id IS NOT NULL THEN oi.line_total ELSE 0 END), 0) = 0 ORDER BY category_name', array['categories', 'products', 'order_items', 'orders'], null, null, 35, 'LEFT JOIN preserva categorias mesmo sem pedidos validos no periodo.', array['select', 'draft'], 39, false),
  ('00000000-0000-0000-0000-000000000450', '00000000-0000-0000-0000-000000000212', 'Lucro por status ativo do produto', 'negocio-lucro-por-status-produto', 'free_select', 'hard', 'Pergunta de negocio: quanto lucro bruto veio de produtos ativos versus inativos em pedidos validos de fevereiro de 2026? Retorne `product_active`, `sales_total` e `gross_profit`, ordenando por `gross_profit` decrescente.', null, 'SELECT p.active AS product_active, sum(oi.line_total) AS sales_total, sum((p.price - p.cost) * oi.quantity) AS gross_profit FROM challenge_data.products p JOIN challenge_data.order_items oi ON oi.product_id = p.id JOIN challenge_data.orders o ON o.id = oi.order_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY p.active ORDER BY gross_profit DESC', array['products', 'order_items', 'orders'], null, null, 35, 'Agrupar por flag ativo mostra quanto a carteira vigente contribui.', array['select', 'draft'], 40, false),
  ('00000000-0000-0000-0000-000000000451', '00000000-0000-0000-0000-000000000212', 'Ranking de pedidos por lucro bruto', 'negocio-ranking-pedidos-lucro-bruto', 'free_select', 'hard', 'Pergunta de negocio: quais pedidos validos tiveram maior lucro bruto estimado em fevereiro de 2026? Retorne `profit_rank`, `order_number` e `gross_profit`, usando `rank()` e limitando em 10.', null, 'SELECT rank() OVER (ORDER BY sum((p.price - p.cost) * oi.quantity) DESC) AS profit_rank, o.order_number, sum((p.price - p.cost) * oi.quantity) AS gross_profit FROM challenge_data.orders o JOIN challenge_data.order_items oi ON oi.order_id = o.id JOIN challenge_data.products p ON p.id = oi.product_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY o.id, o.order_number ORDER BY profit_rank, o.order_number LIMIT 10', array['orders', 'order_items', 'products'], null, null, 35, 'Ranking por lucro bruto destaca pedidos de maior contribuicao.', array['select', 'draft'], 41, false),
  ('00000000-0000-0000-0000-000000000452', '00000000-0000-0000-0000-000000000212', 'Receita por grupo de entrega', 'negocio-receita-grupo-entrega', 'free_select', 'hard', 'Pergunta de negocio: quanto de receita valida de fevereiro de 2026 esta em pedidos com entrega e sem entrega? Retorne `delivery_group`, `order_count` e `sales_total`, usando LEFT JOIN com `shipments`, ordenando por `sales_total` decrescente.', null, 'SELECT CASE WHEN s.id IS NULL THEN ''sem_entrega'' ELSE ''com_entrega'' END AS delivery_group, count(DISTINCT o.id) AS order_count, sum(o.total_amount) AS sales_total FROM challenge_data.orders o LEFT JOIN challenge_data.shipments s ON s.order_id = o.id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY delivery_group ORDER BY sales_total DESC', array['orders', 'shipments'], null, null, 35, 'O CASE classifica pedidos conforme existencia de registro logistico.', array['select', 'draft'], 42, false),
  ('00000000-0000-0000-0000-000000000453', '00000000-0000-0000-0000-000000000212', 'Estornos por dia', 'negocio-estornos-por-dia', 'free_select', 'hard', 'Pergunta de negocio: qual foi o valor estornado por dia em fevereiro de 2026? Retorne `refund_day`, `refund_count` e `refund_total`, ordenando por `refund_day` crescente.', null, 'SELECT ft.transaction_date AS refund_day, count(*) AS refund_count, sum(ft.amount) AS refund_total FROM challenge_data.financial_transactions ft WHERE ft.transaction_date >= DATE ''2026-02-01'' AND ft.transaction_date < DATE ''2026-03-01'' AND ft.type = ''refund'' GROUP BY ft.transaction_date ORDER BY refund_day', array['financial_transactions'], null, null, 35, 'Agrupar estornos por dia mostra concentracao de reversoes.', array['select', 'draft'], 43, false),
  ('00000000-0000-0000-0000-000000000454', '00000000-0000-0000-0000-000000000212', 'Taxa de aprovacao por metodo', 'negocio-taxa-aprovacao-metodo', 'free_select', 'hard', 'Pergunta de negocio: qual a taxa de aprovacao por metodo de pagamento para pedidos de fevereiro de 2026? Retorne `payment_method`, `total_payments`, `paid_payments` e `paid_rate_pct`, ordenando por `paid_rate_pct` decrescente.', null, 'SELECT p.payment_method, count(*) AS total_payments, count(*) FILTER (WHERE p.status = ''paid'') AS paid_payments, round(100.0 * count(*) FILTER (WHERE p.status = ''paid'') / count(*), 2) AS paid_rate_pct FROM challenge_data.payments p JOIN challenge_data.orders o ON o.id = p.order_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' GROUP BY p.payment_method ORDER BY paid_rate_pct DESC, p.payment_method', array['payments', 'orders'], null, null, 35, 'A taxa divide pagamentos pagos pelo total observado por metodo.', array['select', 'draft'], 44, false),
  ('00000000-0000-0000-0000-000000000455', '00000000-0000-0000-0000-000000000212', 'Vendas por categoria e estado', 'negocio-vendas-categoria-estado', 'free_select', 'hard', 'Pergunta de negocio: quais categorias vendem mais por estado em pedidos validos de fevereiro de 2026? Retorne `state`, `category_name` e `sales_total`, ordenando por `state` crescente e `sales_total` decrescente.', null, 'SELECT cu.state, c.name AS category_name, sum(oi.line_total) AS sales_total FROM challenge_data.customers cu JOIN challenge_data.orders o ON o.customer_id = cu.id JOIN challenge_data.order_items oi ON oi.order_id = o.id JOIN challenge_data.products p ON p.id = oi.product_id JOIN challenge_data.categories c ON c.id = p.category_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY cu.state, c.name ORDER BY cu.state, sales_total DESC', array['customers', 'orders', 'order_items', 'products', 'categories'], null, null, 35, 'Esse relatorio cruza geografia do cliente com categoria do produto.', array['select', 'draft'], 45, false),
  ('00000000-0000-0000-0000-000000000456', '00000000-0000-0000-0000-000000000212', 'Frete cobrado por estado', 'negocio-frete-cobrado-por-estado', 'free_select', 'hard', 'Pergunta de negocio: quanto frete foi cobrado por estado em pedidos validos de fevereiro de 2026? Retorne `state`, `order_count`, `shipping_total` e `sales_total`, ordenando por `shipping_total` decrescente.', null, 'SELECT c.state, count(o.id) AS order_count, sum(o.shipping_amount) AS shipping_total, sum(o.total_amount) AS sales_total FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.state ORDER BY shipping_total DESC', array['customers', 'orders'], null, null, 35, 'Frete por estado ajuda a avaliar custo e politica comercial por regiao.', array['select', 'draft'], 46, false),
  ('00000000-0000-0000-0000-000000000457', '00000000-0000-0000-0000-000000000212', 'Baixo estoque com alto giro', 'negocio-baixo-estoque-alto-giro', 'free_select', 'hard', 'Pergunta de negocio: quais produtos venderam pelo menos 2 unidades em fevereiro de 2026 e tem estoque atual menor que 5? Retorne `product_name`, `stock_quantity` e `units_sold`, ordenando por `units_sold` decrescente.', null, 'SELECT p.name AS product_name, p.stock_quantity, sum(oi.quantity) AS units_sold FROM challenge_data.products p JOIN challenge_data.order_items oi ON oi.product_id = p.id JOIN challenge_data.orders o ON o.id = oi.order_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') AND p.stock_quantity < 5 GROUP BY p.id, p.name, p.stock_quantity HAVING sum(oi.quantity) >= 2 ORDER BY units_sold DESC', array['products', 'order_items', 'orders'], null, null, 35, 'Combinar giro e estoque identifica risco de ruptura.', array['select', 'draft'], 47, false),
  ('00000000-0000-0000-0000-000000000458', '00000000-0000-0000-0000-000000000212', 'Pedidos com desconto e margem', 'negocio-pedidos-desconto-margem', 'free_select', 'hard', 'Pergunta de negocio: quais pedidos com desconto tiveram maior margem bruta em fevereiro de 2026? Retorne `order_number`, `discount_amount` e `gross_profit`, considerando pedidos validos com `discount_amount > 0`, ordenando por `gross_profit` decrescente.', null, 'SELECT o.order_number, o.discount_amount, sum((p.price - p.cost) * oi.quantity) AS gross_profit FROM challenge_data.orders o JOIN challenge_data.order_items oi ON oi.order_id = o.id JOIN challenge_data.products p ON p.id = oi.product_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') AND o.discount_amount > 0 GROUP BY o.id, o.order_number, o.discount_amount ORDER BY gross_profit DESC', array['orders', 'order_items', 'products'], null, null, 35, 'Esse relatorio mostra se pedidos com desconto ainda preservam margem.', array['select', 'draft'], 48, false),
  ('00000000-0000-0000-0000-000000000459', '00000000-0000-0000-0000-000000000212', 'Receita por cidade', 'negocio-receita-por-cidade', 'free_select', 'hard', 'Pergunta de negocio: quais cidades geraram mais receita valida em fevereiro de 2026? Retorne `city`, `state`, `order_count` e `sales_total`, considerando pedidos `paid`, `shipped` ou `delivered`, ordenando por `sales_total` decrescente.', null, 'SELECT c.city, c.state, count(o.id) AS order_count, sum(o.total_amount) AS sales_total FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.city, c.state ORDER BY sales_total DESC', array['customers', 'orders'], null, null, 35, 'A receita por cidade combina localizacao do cliente com pedidos validos.', array['select', 'draft'], 49, false),
  ('00000000-0000-0000-0000-000000000460', '00000000-0000-0000-0000-000000000212', 'Top clientes por margem valida', 'negocio-top-clientes-margem-valida', 'free_select', 'hard', 'Pergunta de negocio: quais sao os 5 clientes com maior margem bruta em pedidos validos de fevereiro de 2026? Retorne `full_name`, `sales_total` e `gross_profit`, ordenando por `gross_profit` decrescente e limitando em 5.', null, 'SELECT c.full_name, sum(oi.line_total) AS sales_total, sum((p.price - p.cost) * oi.quantity) AS gross_profit FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id JOIN challenge_data.order_items oi ON oi.order_id = o.id JOIN challenge_data.products p ON p.id = oi.product_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.id, c.full_name ORDER BY gross_profit DESC LIMIT 5', array['customers', 'orders', 'order_items', 'products'], null, null, 35, 'O ranking por margem prioriza clientes que mais contribuem para resultado.', array['select', 'draft'], 50, false),
  ('00000000-0000-0000-0000-000000000461', '00000000-0000-0000-0000-000000000206', 'Produtos com suas categorias ativas', 'joins-basicos-produtos-categorias-ativas', 'free_select', 'medium', 'Liste produtos ativos com sua categoria. Retorne `product_name`, `category_name` e `price`, usando JOIN entre `products` e `categories`, ordenando por `category_name` e `product_name`.', null, 'SELECT p.name AS product_name, c.name AS category_name, p.price FROM challenge_data.products p JOIN challenge_data.categories c ON c.id = p.category_id WHERE p.active = true ORDER BY category_name, product_name', array['products', 'categories'], null, null, 20, 'JOIN basico conecta produtos a categorias pela chave estrangeira.', array['select', 'draft'], 11, false),
  ('00000000-0000-0000-0000-000000000462', '00000000-0000-0000-0000-000000000206', 'Pedidos com cliente e estado', 'joins-basicos-pedidos-cliente-estado', 'free_select', 'medium', 'Liste pedidos com cliente e estado. Retorne `order_number`, `full_name`, `state` e `total_amount`, usando JOIN entre `orders` e `customers`, ordenando por `order_number`.', null, 'SELECT o.order_number, c.full_name, c.state, o.total_amount FROM challenge_data.orders o JOIN challenge_data.customers c ON c.id = o.customer_id ORDER BY o.order_number', array['orders', 'customers'], null, null, 20, 'O pedido guarda o identificador do cliente.', array['select', 'draft'], 12, false),
  ('00000000-0000-0000-0000-000000000463', '00000000-0000-0000-0000-000000000206', 'Pagamentos pagos com numero do pedido', 'joins-basicos-pagamentos-pagos-pedido', 'free_select', 'medium', 'Liste pagamentos pagos com o numero do pedido. Retorne `order_number`, `payment_method` e `amount`, filtrando `payments.status = ''paid''`, ordenando por `amount` decrescente.', null, 'SELECT o.order_number, p.payment_method, p.amount FROM challenge_data.payments p JOIN challenge_data.orders o ON o.id = p.order_id WHERE p.status = ''paid'' ORDER BY p.amount DESC', array['payments', 'orders'], null, null, 20, 'Pagamentos se ligam a pedidos por `order_id`.', array['select', 'draft'], 13, false),
  ('00000000-0000-0000-0000-000000000464', '00000000-0000-0000-0000-000000000206', 'Entregas entregues com pedido', 'joins-basicos-entregas-entregues-pedido', 'free_select', 'medium', 'Liste entregas concluidas com numero do pedido. Retorne `order_number`, `carrier` e `delivered_at`, filtrando `shipments.status = ''delivered''`, ordenando por `delivered_at`.', null, 'SELECT o.order_number, s.carrier, s.delivered_at FROM challenge_data.shipments s JOIN challenge_data.orders o ON o.id = s.order_id WHERE s.status = ''delivered'' ORDER BY s.delivered_at', array['shipments', 'orders'], null, null, 20, 'A entrega possui `order_id` para encontrar o pedido.', array['select', 'draft'], 14, false),
  ('00000000-0000-0000-0000-000000000465', '00000000-0000-0000-0000-000000000206', 'Itens com produto e categoria', 'joins-basicos-itens-produto-categoria', 'free_select', 'hard', 'Liste itens de pedido com produto e categoria. Retorne `order_id`, `product_name`, `category_name`, `quantity` e `line_total`, usando JOINs entre `order_items`, `products` e `categories`, ordenando por `line_total` decrescente e limitando em 12.', null, 'SELECT oi.order_id, p.name AS product_name, c.name AS category_name, oi.quantity, oi.line_total FROM challenge_data.order_items oi JOIN challenge_data.products p ON p.id = oi.product_id JOIN challenge_data.categories c ON c.id = p.category_id ORDER BY oi.line_total DESC LIMIT 12', array['order_items', 'products', 'categories'], null, null, 35, 'Dois JOINs enriquecem itens com produto e categoria.', array['select', 'draft'], 15, false),
  ('00000000-0000-0000-0000-000000000466', '00000000-0000-0000-0000-000000000206', 'Pedidos pagos com cliente e pagamento', 'joins-basicos-pedidos-pagos-cliente-pagamento', 'free_select', 'hard', 'Liste pedidos com cliente e pagamento aprovado. Retorne `full_name`, `order_number`, `payment_method` e `amount`, filtrando pagamentos `paid`, ordenando por `full_name` e `order_number`.', null, 'SELECT c.full_name, o.order_number, p.payment_method, p.amount FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id JOIN challenge_data.payments p ON p.order_id = o.id WHERE p.status = ''paid'' ORDER BY c.full_name, o.order_number', array['customers', 'orders', 'payments'], null, null, 35, 'JOIN em cadeia conecta cliente, pedido e pagamento.', array['select', 'draft'], 16, false),
  ('00000000-0000-0000-0000-000000000467', '00000000-0000-0000-0000-000000000206', 'Produtos de categorias com estoque', 'joins-basicos-produtos-categorias-estoque', 'free_select', 'hard', 'Liste produtos de categorias com estoque atual. Retorne `category_name`, `product_name`, `stock_quantity` e `price`, filtrando produtos com `stock_quantity > 0`, ordenando por `category_name` e `stock_quantity` decrescente.', null, 'SELECT c.name AS category_name, p.name AS product_name, p.stock_quantity, p.price FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id WHERE p.stock_quantity > 0 ORDER BY category_name, p.stock_quantity DESC', array['categories', 'products'], null, null, 35, 'O filtro de estoque fica em produtos, mas o nome da categoria vem do JOIN.', array['select', 'draft'], 17, false),
  ('00000000-0000-0000-0000-000000000468', '00000000-0000-0000-0000-000000000206', 'Pedidos por cliente de Rondonia', 'joins-basicos-pedidos-cliente-rondonia', 'free_select', 'hard', 'Liste pedidos de clientes de Rondonia. Retorne `full_name`, `order_number`, `status` e `total_amount`, usando JOIN entre `customers` e `orders`, filtrando `state = ''Rondonia''`, ordenando por `total_amount` decrescente.', null, 'SELECT c.full_name, o.order_number, o.status, o.total_amount FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id WHERE c.state = ''Rondonia'' ORDER BY o.total_amount DESC', array['customers', 'orders'], null, null, 35, 'Filtros podem usar a tabela de dimensao enquanto valores vem da tabela de fatos.', array['select', 'draft'], 18, false),
  ('00000000-0000-0000-0000-000000000469', '00000000-0000-0000-0000-000000000206', 'Pagamentos com cliente', 'joins-basicos-pagamentos-com-cliente', 'free_select', 'hard', 'Liste pagamentos com nome do cliente. Retorne `full_name`, `payment_method`, `status` e `amount`, usando JOINs entre `payments`, `orders` e `customers`, ordenando por `amount` decrescente e limitando em 10.', null, 'SELECT c.full_name, p.payment_method, p.status, p.amount FROM challenge_data.payments p JOIN challenge_data.orders o ON o.id = p.order_id JOIN challenge_data.customers c ON c.id = o.customer_id ORDER BY p.amount DESC LIMIT 10', array['payments', 'orders', 'customers'], null, null, 35, 'Pagamento chega ao cliente passando pelo pedido.', array['select', 'draft'], 19, false),
  ('00000000-0000-0000-0000-000000000470', '00000000-0000-0000-0000-000000000206', 'Entregas com cliente e status do pedido', 'joins-basicos-entregas-cliente-status-pedido', 'free_select', 'hard', 'Liste entregas com cliente e status do pedido. Retorne `full_name`, `order_number`, `order_status`, `shipment_status` e `carrier`, usando JOINs entre `shipments`, `orders` e `customers`, ordenando por `order_number`.', null, 'SELECT c.full_name, o.order_number, o.status AS order_status, s.status AS shipment_status, s.carrier FROM challenge_data.shipments s JOIN challenge_data.orders o ON o.id = s.order_id JOIN challenge_data.customers c ON c.id = o.customer_id ORDER BY o.order_number', array['shipments', 'orders', 'customers'], null, null, 35, 'Aliases evitam ambiguidade quando duas tabelas tem coluna `status`.', array['select', 'draft'], 20, false),
  ('00000000-0000-0000-0000-000000000471', '00000000-0000-0000-0000-000000000207', 'Clientes sem pedidos pagos', 'joins-intermediarios-clientes-sem-pedidos-pagos', 'free_select', 'medium', 'Use LEFT JOIN para listar clientes que nao tem pedidos `paid`. Retorne `full_name` e `state`, ordenando por `full_name`.', null, 'SELECT c.full_name, c.state FROM challenge_data.customers c LEFT JOIN challenge_data.orders o ON o.customer_id = c.id AND o.status = ''paid'' WHERE o.id IS NULL ORDER BY c.full_name', array['customers', 'orders'], null, null, 20, 'LEFT JOIN com filtro no JOIN encontra ausencias especificas.', array['select', 'draft'], 11, false),
  ('00000000-0000-0000-0000-000000000472', '00000000-0000-0000-0000-000000000207', 'Produtos sem venda valida', 'joins-intermediarios-produtos-sem-venda-valida', 'free_select', 'medium', 'Use LEFT JOIN para listar produtos que nao aparecem em pedidos `paid`, `shipped` ou `delivered`. Retorne `product_name` e `sku`, ordenando por `product_name`.', null, 'SELECT p.name AS product_name, p.sku FROM challenge_data.products p LEFT JOIN challenge_data.order_items oi ON oi.product_id = p.id LEFT JOIN challenge_data.orders o ON o.id = oi.order_id AND o.status IN (''paid'', ''shipped'', ''delivered'') WHERE o.id IS NULL ORDER BY product_name', array['products', 'order_items', 'orders'], null, null, 20, 'A ausencia de pedido valido aparece quando o pedido unido fica nulo.', array['select', 'draft'], 12, false),
  ('00000000-0000-0000-0000-000000000473', '00000000-0000-0000-0000-000000000207', 'Total de pedidos por cliente', 'joins-intermediarios-total-pedidos-cliente', 'free_select', 'medium', 'Liste todos os clientes com quantidade de pedidos. Retorne `full_name` e `order_count`, usando LEFT JOIN, ordenando por `order_count` decrescente e `full_name`.', null, 'SELECT c.full_name, count(o.id) AS order_count FROM challenge_data.customers c LEFT JOIN challenge_data.orders o ON o.customer_id = c.id GROUP BY c.id, c.full_name ORDER BY order_count DESC, c.full_name', array['customers', 'orders'], null, null, 20, 'COUNT da coluna da tabela ligada evita contar linha nula do LEFT JOIN.', array['select', 'draft'], 13, false),
  ('00000000-0000-0000-0000-000000000474', '00000000-0000-0000-0000-000000000207', 'Vendas por categoria com zero', 'joins-intermediarios-vendas-categoria-zero', 'free_select', 'medium', 'Liste todas as categorias com venda total em pedidos validos, incluindo categorias sem venda. Retorne `category_name` e `sales_total`, usando LEFT JOIN e `coalesce`, ordenando por `sales_total` decrescente.', null, 'SELECT c.name AS category_name, coalesce(sum(CASE WHEN o.status IN (''paid'', ''shipped'', ''delivered'') THEN oi.line_total ELSE 0 END), 0) AS sales_total FROM challenge_data.categories c LEFT JOIN challenge_data.products p ON p.category_id = c.id LEFT JOIN challenge_data.order_items oi ON oi.product_id = p.id LEFT JOIN challenge_data.orders o ON o.id = oi.order_id GROUP BY c.name ORDER BY sales_total DESC', array['categories', 'products', 'order_items', 'orders'], null, null, 20, 'CASE dentro da soma preserva categorias sem pedidos validos.', array['select', 'draft'], 14, false),
  ('00000000-0000-0000-0000-000000000475', '00000000-0000-0000-0000-000000000207', 'Margem por categoria em pedidos validos', 'joins-intermediarios-margem-categoria-validos', 'free_select', 'hard', 'Calcule margem bruta por categoria em pedidos validos. Retorne `category_name`, `sales_total` e `gross_profit`, ordenando por `gross_profit` decrescente.', null, 'SELECT c.name AS category_name, sum(oi.line_total) AS sales_total, sum((p.price - p.cost) * oi.quantity) AS gross_profit FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id JOIN challenge_data.order_items oi ON oi.product_id = p.id JOIN challenge_data.orders o ON o.id = oi.order_id WHERE o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.name ORDER BY gross_profit DESC', array['categories', 'products', 'order_items', 'orders'], null, null, 35, 'Agregacoes depois de multiplos JOINs criam metricas por dimensao.', array['select', 'draft'], 15, false),
  ('00000000-0000-0000-0000-000000000476', '00000000-0000-0000-0000-000000000207', 'Pedidos com pagamento sem entrega', 'joins-intermediarios-pagamento-sem-entrega', 'free_select', 'hard', 'Liste pedidos com pagamento `paid` que nao possuem entrega. Retorne `order_number`, `payment_method` e `amount`, usando JOIN em `payments` e LEFT JOIN em `shipments`, ordenando por `amount` decrescente.', null, 'SELECT o.order_number, p.payment_method, p.amount FROM challenge_data.orders o JOIN challenge_data.payments p ON p.order_id = o.id LEFT JOIN challenge_data.shipments s ON s.order_id = o.id WHERE p.status = ''paid'' AND s.id IS NULL ORDER BY p.amount DESC', array['orders', 'payments', 'shipments'], null, null, 35, 'Combinar JOIN e LEFT JOIN permite achar lacunas apos pagamento.', array['select', 'draft'], 16, false),
  ('00000000-0000-0000-0000-000000000477', '00000000-0000-0000-0000-000000000207', 'Receita por estado e status', 'joins-intermediarios-receita-estado-status', 'free_select', 'hard', 'Some receita por estado e status do pedido. Retorne `state`, `status` e `sales_total`, considerando pedidos de fevereiro de 2026, ordenando por `state` e `sales_total` decrescente.', null, 'SELECT c.state, o.status, sum(o.total_amount) AS sales_total FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' GROUP BY c.state, o.status ORDER BY c.state, sales_total DESC', array['customers', 'orders'], null, null, 35, 'Agrupar por duas dimensoes revela composicao do resultado.', array['select', 'draft'], 17, false),
  ('00000000-0000-0000-0000-000000000478', '00000000-0000-0000-0000-000000000207', 'Produtos vendidos por cliente', 'joins-intermediarios-produtos-vendidos-cliente', 'free_select', 'hard', 'Liste cliente e produto com unidades compradas em pedidos validos. Retorne `full_name`, `product_name` e `units_sold`, ordenando por `full_name` e `units_sold` decrescente.', null, 'SELECT c.full_name, p.name AS product_name, sum(oi.quantity) AS units_sold FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id JOIN challenge_data.order_items oi ON oi.order_id = o.id JOIN challenge_data.products p ON p.id = oi.product_id WHERE o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.full_name, p.name ORDER BY c.full_name, units_sold DESC', array['customers', 'orders', 'order_items', 'products'], null, null, 35, 'Esse relatorio percorre cliente, pedido, item e produto.', array['select', 'draft'], 18, false),
  ('00000000-0000-0000-0000-000000000479', '00000000-0000-0000-0000-000000000207', 'Transportadora por status do pedido', 'joins-intermediarios-transportadora-status-pedido', 'free_select', 'hard', 'Conte pedidos por transportadora e status do pedido. Retorne `carrier`, `order_status` e `order_count`, usando JOIN entre `shipments` e `orders`, ordenando por `carrier` e `order_count` decrescente.', null, 'SELECT s.carrier, o.status AS order_status, count(*) AS order_count FROM challenge_data.shipments s JOIN challenge_data.orders o ON o.id = s.order_id GROUP BY s.carrier, o.status ORDER BY s.carrier, order_count DESC', array['shipments', 'orders'], null, null, 35, 'Agrupar status por transportadora mostra composicao logistica.', array['select', 'draft'], 19, false),
  ('00000000-0000-0000-0000-000000000480', '00000000-0000-0000-0000-000000000207', 'Financeiro por cliente', 'joins-intermediarios-financeiro-por-cliente', 'free_select', 'hard', 'Calcule financeiro liquido por cliente em fevereiro de 2026. Retorne `full_name` e `net_amount`, somando `revenue` positivo e demais tipos negativos, ordenando por `net_amount` decrescente.', null, 'SELECT c.full_name, sum(CASE WHEN ft.type = ''revenue'' THEN ft.amount ELSE -ft.amount END) AS net_amount FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id JOIN challenge_data.financial_transactions ft ON ft.order_id = o.id WHERE ft.transaction_date >= DATE ''2026-02-01'' AND ft.transaction_date < DATE ''2026-03-01'' GROUP BY c.id, c.full_name ORDER BY net_amount DESC', array['customers', 'orders', 'financial_transactions'], null, null, 35, 'Financeiro por cliente exige atravessar pedidos ate transacoes.', array['select', 'draft'], 20, false),
  ('00000000-0000-0000-0000-000000000481', '00000000-0000-0000-0000-000000000208', 'CTE pedidos validos', 'ctes-pedidos-validos-total', 'free_select', 'medium', 'Crie a CTE `valid_orders` com pedidos `paid`, `shipped` ou `delivered` de fevereiro de 2026. Retorne `order_count` e `sales_total` a partir dela.', null, 'WITH valid_orders AS (SELECT id, total_amount FROM challenge_data.orders WHERE order_date >= TIMESTAMP ''2026-02-01'' AND order_date < TIMESTAMP ''2026-03-01'' AND status IN (''paid'', ''shipped'', ''delivered'')) SELECT count(id) AS order_count, sum(total_amount) AS sales_total FROM valid_orders', array['orders'], null, null, 20, 'A CTE isola o filtro de pedidos validos antes da agregacao.', array['select', 'draft'], 11, false),
  ('00000000-0000-0000-0000-000000000482', '00000000-0000-0000-0000-000000000208', 'CTE produtos ativos caros', 'ctes-produtos-ativos-caros', 'free_select', 'medium', 'Crie a CTE `active_products` com produtos ativos. Retorne `name` e `price` dos produtos com `price >= 500`, ordenando por `price` decrescente.', null, 'WITH active_products AS (SELECT name, price FROM challenge_data.products WHERE active = true) SELECT name, price FROM active_products WHERE price >= 500 ORDER BY price DESC', array['products'], null, null, 20, 'A CTE separa o filtro de ativo do filtro de preco.', array['select', 'draft'], 12, false),
  ('00000000-0000-0000-0000-000000000483', '00000000-0000-0000-0000-000000000208', 'CTE receita por dia', 'ctes-receita-por-dia', 'free_select', 'medium', 'Crie a CTE `daily_sales` com vendas por dia em pedidos validos de fevereiro de 2026. Retorne `order_day` e `sales_total`, ordenando por `order_day`.', null, 'WITH daily_sales AS (SELECT order_date::date AS order_day, sum(total_amount) AS sales_total FROM challenge_data.orders WHERE order_date >= TIMESTAMP ''2026-02-01'' AND order_date < TIMESTAMP ''2026-03-01'' AND status IN (''paid'', ''shipped'', ''delivered'') GROUP BY order_day) SELECT order_day, sales_total FROM daily_sales ORDER BY order_day', array['orders'], null, null, 20, 'CTE agregada pode ser consultada como uma tabela temporaria da query.', array['select', 'draft'], 13, false),
  ('00000000-0000-0000-0000-000000000484', '00000000-0000-0000-0000-000000000208', 'CTE estoque baixo', 'ctes-estoque-baixo', 'free_select', 'medium', 'Crie a CTE `low_stock` com produtos ativos e estoque menor que 5. Retorne `name`, `sku` e `stock_quantity`, ordenando por `stock_quantity` e `name`.', null, 'WITH low_stock AS (SELECT name, sku, stock_quantity FROM challenge_data.products WHERE active = true AND stock_quantity < 5) SELECT name, sku, stock_quantity FROM low_stock ORDER BY stock_quantity, name', array['products'], null, null, 20, 'A CTE nomeia o conjunto de produtos com risco de estoque.', array['select', 'draft'], 14, false),
  ('00000000-0000-0000-0000-000000000485', '00000000-0000-0000-0000-000000000208', 'CTE ranking clientes', 'ctes-ranking-clientes', 'free_select', 'hard', 'Use CTE `customer_sales` para somar pedidos validos por cliente em fevereiro de 2026. Retorne `full_name`, `total_spent` e `customer_rank` com `rank()` por `total_spent` decrescente, ordenando por `customer_rank`.', null, 'WITH customer_sales AS (SELECT c.full_name, sum(o.total_amount) AS total_spent FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.full_name) SELECT full_name, total_spent, rank() OVER (ORDER BY total_spent DESC) AS customer_rank FROM customer_sales ORDER BY customer_rank, full_name', array['customers', 'orders'], null, null, 35, 'A CTE calcula o total antes da funcao de janela.', array['select', 'draft'], 15, false),
  ('00000000-0000-0000-0000-000000000486', '00000000-0000-0000-0000-000000000208', 'CTEs vendas e estoque categoria', 'ctes-vendas-estoque-categoria', 'free_select', 'hard', 'Crie CTEs `category_sales` e `category_stock`. Retorne `category_name`, `sales_total` e `total_stock`, juntando as CTEs e ordenando por `sales_total` decrescente.', null, 'WITH category_sales AS (SELECT c.id, c.name AS category_name, sum(oi.line_total) AS sales_total FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id JOIN challenge_data.order_items oi ON oi.product_id = p.id JOIN challenge_data.orders o ON o.id = oi.order_id WHERE o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.id, c.name), category_stock AS (SELECT c.id, sum(p.stock_quantity) AS total_stock FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id GROUP BY c.id) SELECT cs.category_name, cs.sales_total, st.total_stock FROM category_sales cs JOIN category_stock st ON st.id = cs.id ORDER BY cs.sales_total DESC', array['categories', 'products', 'order_items', 'orders'], null, null, 35, 'Duas CTEs evitam misturar granularidades de venda e estoque.', array['select', 'draft'], 16, false),
  ('00000000-0000-0000-0000-000000000487', '00000000-0000-0000-0000-000000000208', 'CTE margem produtos', 'ctes-margem-produtos', 'free_select', 'hard', 'Crie a CTE `product_margin` com `product_name`, `category_name` e `margin`. Retorne produtos com margem maior que 200, ordenando por `margin` decrescente.', null, 'WITH product_margin AS (SELECT p.name AS product_name, c.name AS category_name, p.price - p.cost AS margin FROM challenge_data.products p JOIN challenge_data.categories c ON c.id = p.category_id WHERE p.active = true) SELECT product_name, category_name, margin FROM product_margin WHERE margin > 200 ORDER BY margin DESC', array['products', 'categories'], null, null, 35, 'A CTE facilita filtrar uma expressao calculada com alias.', array['select', 'draft'], 17, false),
  ('00000000-0000-0000-0000-000000000488', '00000000-0000-0000-0000-000000000208', 'CTE pagamentos por metodo', 'ctes-pagamentos-por-metodo', 'free_select', 'hard', 'Crie a CTE `method_totals` com total pago por metodo em fevereiro de 2026. Retorne `payment_method`, `payment_count` e `paid_total` apenas para metodos com `paid_total >= 1000`, ordenando por `paid_total` decrescente.', null, 'WITH method_totals AS (SELECT payment_method, count(*) AS payment_count, sum(amount) AS paid_total FROM challenge_data.payments WHERE paid_at >= TIMESTAMP ''2026-02-01'' AND paid_at < TIMESTAMP ''2026-03-01'' AND status = ''paid'' GROUP BY payment_method) SELECT payment_method, payment_count, paid_total FROM method_totals WHERE paid_total >= 1000 ORDER BY paid_total DESC', array['payments'], null, null, 35, 'A CTE permite filtrar uma agregacao pelo alias.', array['select', 'draft'], 18, false),
  ('00000000-0000-0000-0000-000000000489', '00000000-0000-0000-0000-000000000208', 'CTE pedidos com lucro', 'ctes-pedidos-com-lucro', 'free_select', 'hard', 'Crie a CTE `order_profit` com lucro bruto por pedido valido. Retorne `order_number` e `gross_profit` para pedidos com `gross_profit > 500`, ordenando por `gross_profit` decrescente.', null, 'WITH order_profit AS (SELECT o.order_number, sum((p.price - p.cost) * oi.quantity) AS gross_profit FROM challenge_data.orders o JOIN challenge_data.order_items oi ON oi.order_id = o.id JOIN challenge_data.products p ON p.id = oi.product_id WHERE o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY o.order_number) SELECT order_number, gross_profit FROM order_profit WHERE gross_profit > 500 ORDER BY gross_profit DESC', array['orders', 'order_items', 'products'], null, null, 35, 'A CTE transforma margem por pedido em uma tabela filtravel.', array['select', 'draft'], 19, false),
  ('00000000-0000-0000-0000-000000000490', '00000000-0000-0000-0000-000000000208', 'CTE clientes por estado', 'ctes-clientes-por-estado-receita', 'free_select', 'hard', 'Use CTE `state_sales` para somar receita valida por estado em fevereiro de 2026. Retorne `state`, `customer_count` e `sales_total`, ordenando por `sales_total` decrescente.', null, 'WITH state_sales AS (SELECT c.state, count(DISTINCT c.id) AS customer_count, sum(o.total_amount) AS sales_total FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.state) SELECT state, customer_count, sales_total FROM state_sales ORDER BY sales_total DESC', array['customers', 'orders'], null, null, 35, 'COUNT DISTINCT evita duplicar clientes com varios pedidos.', array['select', 'draft'], 20, false),
  ('00000000-0000-0000-0000-000000000491', '00000000-0000-0000-0000-000000000209', 'UNION clientes SP RJ', 'union-clientes-sp-rj', 'free_select', 'medium', 'Use UNION para combinar clientes de SP e RJ. Retorne `full_name`, `state` e `region_group`, usando `region_group = ''sudeste''`, ordenando por `state` e `full_name`.', null, 'SELECT full_name, state, ''sudeste'' AS region_group FROM challenge_data.customers WHERE state = ''SP'' UNION SELECT full_name, state, ''sudeste'' AS region_group FROM challenge_data.customers WHERE state = ''RJ'' ORDER BY state, full_name', array['customers'], null, null, 20, 'UNION combina consultas com as mesmas colunas.', array['select', 'draft'], 11, false),
  ('00000000-0000-0000-0000-000000000492', '00000000-0000-0000-0000-000000000209', 'UNION ALL produtos ativos e inativos', 'union-produtos-ativos-inativos', 'free_select', 'medium', 'Use UNION ALL para listar produtos ativos e inativos com um rotulo. Retorne `product_name` e `product_status`, ordenando por `product_status` e `product_name`.', null, 'SELECT name AS product_name, ''ativo'' AS product_status FROM challenge_data.products WHERE active = true UNION ALL SELECT name AS product_name, ''inativo'' AS product_status FROM challenge_data.products WHERE active = false ORDER BY product_status, product_name', array['products'], null, null, 20, 'UNION ALL preserva todos os resultados das duas consultas.', array['select', 'draft'], 12, false),
  ('00000000-0000-0000-0000-000000000493', '00000000-0000-0000-0000-000000000209', 'UNION pedidos pagos e entregues', 'union-pedidos-pagos-entregues', 'free_select', 'medium', 'Use UNION para combinar pedidos `paid` e `delivered`. Retorne `order_number`, `status` e `total_amount`, ordenando por `status` e `order_number`.', null, 'SELECT order_number, status, total_amount FROM challenge_data.orders WHERE status = ''paid'' UNION SELECT order_number, status, total_amount FROM challenge_data.orders WHERE status = ''delivered'' ORDER BY status, order_number', array['orders'], null, null, 20, 'UNION remove duplicatas e exige colunas compativeis.', array['select', 'draft'], 13, false),
  ('00000000-0000-0000-0000-000000000494', '00000000-0000-0000-0000-000000000209', 'UNION eventos de pedido e pagamento', 'union-eventos-pedido-pagamento', 'free_select', 'medium', 'Use UNION ALL para montar uma linha do tempo com pedidos e pagamentos antes de 2026-02-05. Retorne `reference`, `event_type` e `event_at`, ordenando por `event_at` e `event_type`.', null, 'SELECT order_number AS reference, ''order'' AS event_type, order_date AS event_at FROM challenge_data.orders WHERE order_date < TIMESTAMP ''2026-02-05'' UNION ALL SELECT payment_method AS reference, ''payment'' AS event_type, paid_at AS event_at FROM challenge_data.payments WHERE paid_at < TIMESTAMP ''2026-02-05'' AND paid_at IS NOT NULL ORDER BY event_at, event_type', array['orders', 'payments'], null, null, 20, 'UNION ALL permite mesclar eventos de tabelas diferentes em um formato comum.', array['select', 'draft'], 14, false),
  ('00000000-0000-0000-0000-000000000495', '00000000-0000-0000-0000-000000000209', 'UNION categorias e produtos caros', 'union-categorias-produtos-caros', 'free_select', 'hard', 'Use UNION ALL para combinar categorias e produtos com preco maior ou igual a 1000. Retorne `name` e `source`, onde categorias usam `source = ''category''` e produtos usam `source = ''product''`, ordenando por `source` e `name`.', null, 'SELECT name, ''category'' AS source FROM challenge_data.categories UNION ALL SELECT name, ''product'' AS source FROM challenge_data.products WHERE price >= 1000 ORDER BY source, name', array['categories', 'products'], null, null, 35, 'As duas consultas precisam produzir colunas com tipos compativeis.', array['select', 'draft'], 15, false),
  ('00000000-0000-0000-0000-000000000496', '00000000-0000-0000-0000-000000000209', 'UNION receitas e estornos', 'union-receitas-estornos', 'free_select', 'hard', 'Use UNION ALL para combinar transacoes `revenue` e `refund` de fevereiro de 2026. Retorne `order_id`, `type` e `amount`, ordenando por `type` e `amount` decrescente.', null, 'SELECT order_id, type, amount FROM challenge_data.financial_transactions WHERE transaction_date >= DATE ''2026-02-01'' AND transaction_date < DATE ''2026-03-01'' AND type = ''revenue'' UNION ALL SELECT order_id, type, amount FROM challenge_data.financial_transactions WHERE transaction_date >= DATE ''2026-02-01'' AND transaction_date < DATE ''2026-03-01'' AND type = ''refund'' ORDER BY type, amount DESC', array['financial_transactions'], null, null, 35, 'UNION ALL mantem todas as transacoes financeiras selecionadas.', array['select', 'draft'], 16, false),
  ('00000000-0000-0000-0000-000000000497', '00000000-0000-0000-0000-000000000209', 'UNION buscas por nome', 'union-buscas-por-nome', 'free_select', 'hard', 'Use UNION ALL para combinar clientes com nome contendo `Silva` e produtos com nome contendo `SQL`. Retorne `result_name` e `result_type`, ordenando por `result_type` e `result_name`.', null, 'SELECT full_name AS result_name, ''customer'' AS result_type FROM challenge_data.customers WHERE full_name LIKE ''%Silva%'' UNION ALL SELECT name AS result_name, ''product'' AS result_type FROM challenge_data.products WHERE name LIKE ''%SQL%'' ORDER BY result_type, result_name', array['customers', 'products'], null, null, 35, 'UNION pode servir como busca simples em entidades diferentes.', array['select', 'draft'], 17, false),
  ('00000000-0000-0000-0000-000000000498', '00000000-0000-0000-0000-000000000209', 'UNION regioes de clientes', 'union-regioes-clientes', 'free_select', 'hard', 'Use UNION ALL para classificar clientes de Rondonia e AM como `norte`, e clientes de SP, RJ e MG como `sudeste`. Retorne `full_name`, `state` e `region`, ordenando por `region` e `full_name`.', null, 'SELECT full_name, state, ''norte'' AS region FROM challenge_data.customers WHERE state IN (''Rondonia'', ''AM'') UNION ALL SELECT full_name, state, ''sudeste'' AS region FROM challenge_data.customers WHERE state IN (''SP'', ''RJ'', ''MG'') ORDER BY region, full_name', array['customers'], null, null, 35, 'Duas consultas com filtros diferentes podem virar um resultado classificado.', array['select', 'draft'], 18, false),
  ('00000000-0000-0000-0000-000000000499', '00000000-0000-0000-0000-000000000209', 'UNION contagens operacionais', 'union-contagens-operacionais', 'free_select', 'hard', 'Use UNION ALL para combinar contagem por metodo de pagamento e contagem por status de pedido. Retorne `label`, `source` e `total`, ordenando por `source` e `label`.', null, 'SELECT payment_method AS label, ''payment_method'' AS source, count(*) AS total FROM challenge_data.payments GROUP BY payment_method UNION ALL SELECT status AS label, ''order_status'' AS source, count(*) AS total FROM challenge_data.orders GROUP BY status ORDER BY source, label', array['payments', 'orders'], null, null, 35, 'Agregacoes separadas podem ser empilhadas se os formatos coincidirem.', array['select', 'draft'], 19, false),
  ('00000000-0000-0000-0000-000000000500', '00000000-0000-0000-0000-000000000209', 'UNION CTE pedidos selecionados', 'union-cte-pedidos-selecionados', 'free_select', 'hard', 'Crie a CTE `selected_orders` usando UNION ALL para combinar pedidos com `total_amount >= 2000` e pedidos `pending`. Retorne `order_number`, `status` e `total_amount`, ordenando por `total_amount` decrescente.', null, 'WITH selected_orders AS (SELECT order_number, status, total_amount FROM challenge_data.orders WHERE total_amount >= 2000 UNION ALL SELECT order_number, status, total_amount FROM challenge_data.orders WHERE status = ''pending'') SELECT order_number, status, total_amount FROM selected_orders ORDER BY total_amount DESC', array['orders'], null, null, 35, 'UNION dentro de CTE permite tratar a combinacao antes da ordenacao final.', array['select', 'draft'], 20, false),
  ('00000000-0000-0000-0000-000000000501', '00000000-0000-0000-0000-000000000210', 'Revisao clientes com gasto valido', 'revisao-clientes-gasto-valido', 'free_select', 'medium', 'Com uma CTE `valid_orders`, retorne os 5 clientes com maior gasto em pedidos validos. Retorne `full_name` e `total_spent`, ordenando por `total_spent` decrescente e limitando em 5.', null, 'WITH valid_orders AS (SELECT customer_id, total_amount FROM challenge_data.orders WHERE status IN (''paid'', ''shipped'', ''delivered'')) SELECT c.full_name, sum(v.total_amount) AS total_spent FROM valid_orders v JOIN challenge_data.customers c ON c.id = v.customer_id GROUP BY c.full_name ORDER BY total_spent DESC LIMIT 5', array['orders', 'customers'], null, null, 20, 'A CTE separa o filtro de pedidos antes do ranking por cliente.', array['select', 'draft'], 11, false),
  ('00000000-0000-0000-0000-000000000502', '00000000-0000-0000-0000-000000000210', 'Revisao produtos acima da media', 'revisao-produtos-acima-media', 'free_select', 'medium', 'Use CTE `category_avg` para calcular preco medio por categoria. Retorne `product_name`, `price` e `average_price` dos produtos com preco acima da media da categoria, ordenando por `price` decrescente.', null, 'WITH category_avg AS (SELECT category_id, round(avg(price), 2) AS average_price FROM challenge_data.products GROUP BY category_id) SELECT p.name AS product_name, p.price, ca.average_price FROM challenge_data.products p JOIN category_avg ca ON ca.category_id = p.category_id WHERE p.price > ca.average_price ORDER BY p.price DESC', array['products'], null, null, 20, 'A media por categoria vira referencia para comparar cada produto.', array['select', 'draft'], 12, false),
  ('00000000-0000-0000-0000-000000000503', '00000000-0000-0000-0000-000000000210', 'Revisao clientes sem entregas', 'revisao-clientes-sem-entregas', 'free_select', 'medium', 'Liste clientes que nao tem pedidos entregues (`orders.status = ''delivered''`). Retorne `full_name` e `state`, usando LEFT JOIN, ordenando por `full_name`.', null, 'SELECT c.full_name, c.state FROM challenge_data.customers c LEFT JOIN challenge_data.orders o ON o.customer_id = c.id AND o.status = ''delivered'' WHERE o.id IS NULL ORDER BY c.full_name', array['customers', 'orders'], null, null, 20, 'LEFT JOIN com filtro no ON encontra clientes sem relacionamento do tipo desejado.', array['select', 'draft'], 13, false),
  ('00000000-0000-0000-0000-000000000504', '00000000-0000-0000-0000-000000000210', 'Revisao pedidos pagos sem envio', 'revisao-pedidos-pagos-sem-envio', 'free_select', 'medium', 'Liste pedidos `paid` que nao possuem registro em `shipments`. Retorne `order_number`, `total_amount` e `status`, usando LEFT JOIN, ordenando por `total_amount` decrescente.', null, 'SELECT o.order_number, o.total_amount, o.status FROM challenge_data.orders o LEFT JOIN challenge_data.shipments s ON s.order_id = o.id WHERE o.status = ''paid'' AND s.id IS NULL ORDER BY o.total_amount DESC', array['orders', 'shipments'], null, null, 20, 'Esse padrao combina filtro de status e ausencia de entrega.', array['select', 'draft'], 14, false),
  ('00000000-0000-0000-0000-000000000505', '00000000-0000-0000-0000-000000000210', 'Revisao categoria estoque vendas', 'revisao-categoria-estoque-vendas', 'free_select', 'hard', 'Com CTEs `category_stock` e `category_sales`, retorne `category_name`, `total_stock` e `sales_total` para todas as categorias. Ordene por `sales_total` decrescente.', null, 'WITH category_stock AS (SELECT c.id, c.name AS category_name, sum(p.stock_quantity) AS total_stock FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id GROUP BY c.id, c.name), category_sales AS (SELECT c.id, coalesce(sum(oi.line_total), 0) AS sales_total FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id LEFT JOIN challenge_data.order_items oi ON oi.product_id = p.id GROUP BY c.id) SELECT cs.category_name, cs.total_stock, s.sales_total FROM category_stock cs JOIN category_sales s ON s.id = cs.id ORDER BY s.sales_total DESC', array['categories', 'products', 'order_items'], null, null, 35, 'Separar CTEs impede que estoque seja multiplicado por itens vendidos.', array['select', 'draft'], 15, false),
  ('00000000-0000-0000-0000-000000000506', '00000000-0000-0000-0000-000000000210', 'Revisao descontos e frete gratis', 'revisao-descontos-frete-gratis', 'free_select', 'hard', 'Use UNION para listar pedidos com desconto e pedidos com frete gratis. Retorne `order_number`, `reason` e `amount`, ordenando por `reason` e `order_number`.', null, 'SELECT order_number, ''discount'' AS reason, discount_amount AS amount FROM challenge_data.orders WHERE discount_amount > 0 UNION SELECT order_number, ''free_shipping'' AS reason, shipping_amount AS amount FROM challenge_data.orders WHERE shipping_amount = 0 ORDER BY reason, order_number', array['orders'], null, null, 35, 'UNION combina dois criterios comerciais em uma lista unica.', array['select', 'draft'], 16, false),
  ('00000000-0000-0000-0000-000000000507', '00000000-0000-0000-0000-000000000210', 'Revisao linha do tempo recente', 'revisao-linha-tempo-recente', 'free_select', 'hard', 'Com CTE `events`, combine pedidos e pagamentos usando UNION ALL. Retorne `reference`, `event_type` e `event_at` para eventos a partir de 2026-02-18, ordenando por `event_at` e `event_type`.', null, 'WITH events AS (SELECT order_number AS reference, ''order'' AS event_type, order_date AS event_at FROM challenge_data.orders UNION ALL SELECT payment_method AS reference, ''payment'' AS event_type, paid_at AS event_at FROM challenge_data.payments WHERE paid_at IS NOT NULL) SELECT reference, event_type, event_at FROM events WHERE event_at >= TIMESTAMP ''2026-02-18'' ORDER BY event_at, event_type', array['orders', 'payments'], null, null, 35, 'A CTE cria uma linha do tempo combinada antes do filtro final.', array['select', 'draft'], 17, false),
  ('00000000-0000-0000-0000-000000000508', '00000000-0000-0000-0000-000000000210', 'Revisao unidades validas por produto', 'revisao-unidades-validas-produto', 'free_select', 'hard', 'Some unidades vendidas por produto em pedidos que nao estejam `cancelled`. Retorne `product_name` e `units_sold`, ordenando por `units_sold` decrescente e `product_name`.', null, 'SELECT p.name AS product_name, sum(oi.quantity) AS units_sold FROM challenge_data.products p JOIN challenge_data.order_items oi ON oi.product_id = p.id JOIN challenge_data.orders o ON o.id = oi.order_id WHERE o.status <> ''cancelled'' GROUP BY p.name ORDER BY units_sold DESC, product_name', array['products', 'order_items', 'orders'], null, null, 35, 'A revisao combina JOIN, filtro, agregacao e ordenacao.', array['select', 'draft'], 18, false),
  ('00000000-0000-0000-0000-000000000509', '00000000-0000-0000-0000-000000000210', 'Revisao financeiro liquido pedido', 'revisao-financeiro-liquido-pedido', 'free_select', 'hard', 'Calcule o valor liquido por pedido usando transacoes financeiras. Retorne `order_number` e `net_amount`, tratando `refund`, `fee` e `shipping_cost` como negativos, ordenando por `net_amount` decrescente.', null, 'SELECT o.order_number, sum(CASE WHEN ft.type IN (''refund'', ''fee'', ''shipping_cost'') THEN -ft.amount ELSE ft.amount END) AS net_amount FROM challenge_data.orders o JOIN challenge_data.financial_transactions ft ON ft.order_id = o.id GROUP BY o.order_number ORDER BY net_amount DESC', array['orders', 'financial_transactions'], null, null, 35, 'CASE aplica sinal de negocio antes de somar por pedido.', array['select', 'draft'], 19, false),
  ('00000000-0000-0000-0000-000000000510', '00000000-0000-0000-0000-000000000210', 'Revisao final categorias', 'revisao-final-categorias-inativo', 'free_select', 'hard', 'Com CTEs `category_sales` e `category_stock`, retorne `category_name`, `sales_total` e `total_stock` para categorias com `sales_total > 500`. Ordene por `sales_total` decrescente.', null, 'WITH category_sales AS (SELECT c.name AS category_name, sum(oi.line_total) AS sales_total FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id JOIN challenge_data.order_items oi ON oi.product_id = p.id GROUP BY c.name), category_stock AS (SELECT c.name AS category_name, sum(p.stock_quantity) AS total_stock FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id GROUP BY c.name) SELECT s.category_name, s.sales_total, st.total_stock FROM category_sales s JOIN category_stock st ON st.category_name = s.category_name WHERE s.sales_total > 500 ORDER BY s.sales_total DESC', array['categories', 'products', 'order_items'], null, null, 35, 'Esse desafio revisa CTEs, JOIN entre CTEs, filtro e ordenacao.', array['select', 'draft'], 20, false)
on conflict (id) do nothing;

insert into challenge_hints (challenge_id, hint_order, content)
values
  ('00000000-0000-0000-0000-000000000411', 1, 'Filtre `financial_transactions` por `transaction_date` em fevereiro de 2026.'),
  ('00000000-0000-0000-0000-000000000411', 2, 'Some `amount` apenas quando `type = ''revenue''` e use o alias `revenue_total`.'),
  ('00000000-0000-0000-0000-000000000412', 1, 'Use `CASE` para manter `revenue` positivo e inverter os demais tipos.'),
  ('00000000-0000-0000-0000-000000000412', 2, 'A coluna final deve se chamar `net_profit`.'),
  ('00000000-0000-0000-0000-000000000413', 1, 'Filtre o mes e mantenha apenas os tres status validos.'),
  ('00000000-0000-0000-0000-000000000413', 2, 'Use `count(*) AS order_count` e ordene do maior volume para o menor.'),
  ('00000000-0000-0000-0000-000000000414', 1, 'Agrupe por `status` depois de filtrar fevereiro.'),
  ('00000000-0000-0000-0000-000000000414', 2, 'Use `round(avg(total_amount), 2)` como `average_order_value`.'),
  ('00000000-0000-0000-0000-000000000415', 1, 'Use JOIN de `categories` para `products`, `order_items` e `orders`.'),
  ('00000000-0000-0000-0000-000000000415', 2, 'Agrupe por `c.name` e use os aliases `category_name` e `sales_total`.'),
  ('00000000-0000-0000-0000-000000000416', 1, 'Calcule `(p.price - p.cost) * oi.quantity` antes de somar.'),
  ('00000000-0000-0000-0000-000000000416', 2, 'A ordenacao deve ser por `gross_profit` em ordem decrescente.'),
  ('00000000-0000-0000-0000-000000000417', 1, 'Some `oi.quantity`, nao `line_total`.'),
  ('00000000-0000-0000-0000-000000000417', 2, 'Use desempate por `category_name` crescente.'),
